result = filter_nonce({'id': 97, 'name': 'ember', 'tier': 'b'}, ['id', 'name', 'owner'])
result = {k: v for k, v in result['value'].items() if v is not None}
assert result == {'id': 97, 'name': 'ember'}
print('Success')

